  {wavefunction : ℝ → SchwartzMap ℝ ℂ} {timeDerivative : ℝ → ℝ → ℂ}
  {represents_propagator :
    ∀ (t : ℝ),
      (wavefunction t).toLp 2 MeasureTheory.volume =
        (evolution.propagator t) ((wavefunction 0).toLp 2 MeasureTheory.volume)}
  {hasDerivAt_re : ∀ (t x : ℝ), HasDerivAt (fun τ => ((wavefunction τ) x).re) (timeDerivative t x).re t}
  {hasDerivAt_im : ∀ (t x : ℝ), HasDerivAt (fun τ => ((wavefunction τ) x).im) (timeDerivative t x).im t}
  {schrodinger :
    ∀ (t x : ℝ),
      Complex.I * ↑evolution.hbar * timeDerivative t x =
        -↑κ * (QuantumMechanics.SingleParticle.Continuum.schwartzSpatialSecondDerivative1D (wavefunction t)) x +
          ↑(potential x) * (wavefunction t) x}
  {wavefunction_1 : ℝ → SchwartzMap ℝ ℂ} {timeDerivative_1 : ℝ → ℝ → ℂ}
  {represents_propagator_1 :
    ∀ (t : ℝ),
      (wavefunction_1 t).toLp 2 MeasureTheory.volume =
        (evolution.propagator t) ((wavefunction_1 0).toLp 2 MeasureTheory.volume)}
  {hasDerivAt_re_1 : ∀ (t x : ℝ), HasDerivAt (fun τ => ((wavefunction_1 τ) x).re) (timeDerivative_1 t x).re t}
  {hasDerivAt_im_1 : ∀ (t x : ℝ), HasDerivAt (fun τ => ((wavefunction_1 τ) x).im) (timeDerivative_1 t x).im t}
  {schrodinger_1 :
    ∀ (t x : ℝ),
      Complex.I * ↑evolution.hbar * timeDerivative_1 t x =
        -↑κ * (QuantumMechanics.SingleParticle.Continuum.schwartzSpatialSecondDerivative1D (wavefunction_1 t)) x +
          ↑(potential x) * (wavefunction_1 t) x},
  { wavefunction := wavefunction, timeDerivative := timeDerivative, represents_propagator := represents_propagator,
        hasDerivAt_re := hasDerivAt_re, hasDerivAt_im := hasDerivAt_im, schrodinger := schrodinger } =
      { wavefunction := wavefunction_1, timeDerivative := timeDerivative_1,
        represents_propagator := represents_propagator_1, hasDerivAt_re := hasDerivAt_re_1,
        hasDerivAt_im := hasDerivAt_im_1, schrodinger := schrodinger_1 } →
    wavefunction = wavefunction_1 ∧ timeDerivative = timeDerivative_1

