∀ {Ω : Type u_2} {inst : Fintype Ω} {direction : Ω → Fin 3 → ℝ} {unit_direction : ∀ (p : Ω), ∑ i, direction p i ^ 2 = 1}
  {kernel : Ω → Ω → ℝ} {kernel_nonneg : ∀ (p q : Ω), 0 ≤ kernel p q} {totalRate firstCoefficient secondCoefficient : ℝ}
  {total_moment : ∀ (p : Ω), ∑ q, kernel p q = totalRate}
  {first_moment : ∀ (p : Ω) (i : Fin 3), ∑ q, kernel p q * direction q i = firstCoefficient * direction p i}
  {second_moment :
    ∀ (p : Ω) (i j : Fin 3),
      ∑ q, kernel p q * (direction q i * direction q j) =
        ((totalRate - secondCoefficient) / 3 * if i = j then 1 else 0) +
          secondCoefficient * (direction p i * direction p j)}
  {direction_1 : Ω → Fin 3 → ℝ} {unit_direction_1 : ∀ (p : Ω), ∑ i, direction_1 p i ^ 2 = 1} {kernel_1 : Ω → Ω → ℝ}
  {kernel_nonneg_1 : ∀ (p q : Ω), 0 ≤ kernel_1 p q} {totalRate_1 firstCoefficient_1 secondCoefficient_1 : ℝ}
  {total_moment_1 : ∀ (p : Ω), ∑ q, kernel_1 p q = totalRate_1}
  {first_moment_1 : ∀ (p : Ω) (i : Fin 3), ∑ q, kernel_1 p q * direction_1 q i = firstCoefficient_1 * direction_1 p i}
  {second_moment_1 :
    ∀ (p : Ω) (i j : Fin 3),
      ∑ q, kernel_1 p q * (direction_1 q i * direction_1 q j) =
        ((totalRate_1 - secondCoefficient_1) / 3 * if i = j then 1 else 0) +
          secondCoefficient_1 * (direction_1 p i * direction_1 p j)},
  { direction := direction, unit_direction := unit_direction, kernel := kernel, kernel_nonneg := kernel_nonneg,
        totalRate := totalRate, firstCoefficient := firstCoefficient, secondCoefficient := secondCoefficient,
        total_moment := total_moment, first_moment := first_moment, second_moment := second_moment } =
