∀ {M : Type u_1} {d : Type u_2} {H : Type u_3} {inst : NormedAddCommGroup H} {inst_1 : InnerProductSpace ℂ H}
  {inst_2 : CompleteSpace H} {inst_3 : FiniteDimensional ℂ H} {reverse : M → M}
  {system : M → QuantumTheory.LinearResponse.BoundedFreeSystem H} {hbar : ℝ}
  {system_hbar : ∀ (m : M), (system m).hbar = hbar} {density : M → QuantumTheory.DensityOperator H}
  {density_stationary : ∀ (m : M), Commute (↑(system m).hamiltonian) (density m).op}
  {transform : (H →L[ℂ] H) → H →L[ℂ] H}
  {transform_add : ∀ (A B : H →L[ℂ] H), transform (A + B) = transform A + transform B}
  {transform_mul : ∀ (A B : H →L[ℂ] H), transform (A * B) = transform A * transform B}
  {transform_star : ∀ (A : H →L[ℂ] H), transform (star A) = star (transform A)}
  {transform_smul : ∀ (c : ℂ) (A : H →L[ℂ] H), transform (c • A) = star c • transform A}
  {transform_exp : ∀ (A : H →L[ℂ] H), transform (NormedSpace.exp A) = NormedSpace.exp (transform A)}
  {transform_trace :
    ∀ (A : H →L[ℂ] H),
      ContinuousLinearMap.finiteDimensionalOperatorTrace (transform A) =
        star (ContinuousLinearMap.finiteDimensionalOperatorTrace A)}
  {hamiltonian_reverse : ∀ (m : M), transform ↑(system m).hamiltonian = ↑(system (reverse m)).hamiltonian}
  {density_reverse : ∀ (m : M), transform (density m).op = (density (reverse m)).op}
  {current : M → d → QuantumTheory.Observable H}
  {current_reverse : ∀ (m : M) (i : d), transform ↑(current m i) = -↑(current (reverse m) i)}
  {contact : M → d → d → QuantumTheory.Observable H}
  {contact_reverse : ∀ (m : M) (i j : d), transform ↑(contact m i j) = ↑(contact (reverse m) j i)} {reverse_1 : M → M}
  {system_1 : M → QuantumTheory.LinearResponse.BoundedFreeSystem H} {hbar_1 : ℝ}
  {system_hbar_1 : ∀ (m : M), (system_1 m).hbar = hbar_1} {density_1 : M → QuantumTheory.DensityOperator H}
  {density_stationary_1 : ∀ (m : M), Commute (↑(system_1 m).hamiltonian) (density_1 m).op}
  {transform_1 : (H →L[ℂ] H) → H →L[ℂ] H}
  {transform_add_1 : ∀ (A B : H →L[ℂ] H), transform_1 (A + B) = transform_1 A + transform_1 B}
  {transform_mul_1 : ∀ (A B : H →L[ℂ] H), transform_1 (A * B) = transform_1 A * transform_1 B}
  {transform_star_1 : ∀ (A : H →L[ℂ] H), transform_1 (star A) = star (transform_1 A)}
  {transform_smul_1 : ∀ (c : ℂ) (A : H →L[ℂ] H), transform_1 (c • A) = star c • transform_1 A}
  {transform_exp_1 : ∀ (A : H →L[ℂ] H), transform_1 (NormedSpace.exp A) = NormedSpace.exp (transform_1 A)}
  {transform_trace_1 :
    ∀ (A : H →L[ℂ] H),
      ContinuousLinearMap.finiteDimensionalOperatorTrace (transform_1 A) =
        star (ContinuousLinearMap.finiteDimensionalOperatorTrace A)}
  {hamiltonian_reverse_1 : ∀ (m : M), transform_1 ↑(system_1 m).hamiltonian = ↑(system_1 (reverse_1 m)).hamiltonian}
  {density_reverse_1 : ∀ (m : M), transform_1 (density_1 m).op = (density_1 (reverse_1 m)).op}
  {current_1 : M → d → QuantumTheory.Observable H}
  {current_reverse_1 : ∀ (m : M) (i : d), transform_1 ↑(current_1 m i) = -↑(current_1 (reverse_1 m) i)}
  {contact_1 : M → d → d → QuantumTheory.Observable H}
  {contact_reverse_1 : ∀ (m : M) (i j : d), transform_1 ↑(contact_1 m i j) = ↑(contact_1 (reverse_1 m) j i)},
  { reverse := reverse, system := system, hbar := hbar, system_hbar := system_hbar, density := density,
        density_stationary := density_stationary, transform := transform, transform_add := transform_add,
        transform_mul := transform_mul, transform_star := transform_star, transform_smul := transform_smul,
        transform_exp := transform_exp, transform_trace := transform_trace, hamiltonian_reverse := hamiltonian_reverse,
        density_reverse := density_reverse, current := current, current_reverse := current_reverse, contact := contact,
        contact_reverse := contact_reverse } =
      { reverse := reverse_1, system := system_1, hbar := hbar_1, system_hbar := system_hbar_1, density := density_1,
        density_stationary := density_stationary_1, transform := transform_1, transform_add := transform_add_1,
        transform_mul := transform_mul_1, transform_star := transform_star_1, transform_smul := transform_smul_1,
        transform_exp := transform_exp_1, transform_trace := transform_trace_1,
        hamiltonian_reverse := hamiltonian_reverse_1, density_reverse := density_reverse_1, current := current_1,
        current_reverse := current_reverse_1, contact := contact_1, contact_reverse := contact_reverse_1 } →
    reverse = reverse_1 ∧
      system = system_1 ∧ hbar = hbar_1 ∧ density = density_1 ∧ ⋯ ∧ current = current_1 ∧ contact = contact_1

